# 节点: tr[u][26] 转移(Trie图), fail[u], cnt[u]
def build():
  q = deque(根的所有直接儿子)   # 根儿子 fail=0
  while q:
    u = q.popleft()
    for c in range(26):
      v = tr[u][c]
      if v:
        fail[v] = tr[fail[u]][c]
        q.append(v)
      else:
        tr[u][c] = tr[fail[u]][c]   # 补全 Trie图
def query(text):
  u = 0; res = 0
  for ch in text:
    u = tr[u][ch]
    v = u
    while v and cnt[v]: res += cnt[v]; cnt[v]=0; v = fail[v]
  return res
# 求每个模式次数: 命中节点 acc++ -> 按 fail 树逆拓扑累加
